// ===========================================================================
// Free METABELIAN group of rank 2, class c :  exact model and E2 torsion test.
//
// Model (classical, Magnus):  for F = F_2 free of rank 2,  F'/F''  is a FREE
// cyclic module of rank 1 over Z[F/F'] = Z[s^{+-1}, t^{+-1}], generated by
// w = [x,y], with  a^x = s.a ,  a^y = t.a  (paper convention a^g = g^{-1}ag).
// Writing s = 1+S, t = 1+T, the lower central series corresponds to powers of
// the augmentation ideal I = (S,T):
//        gamma_j / (gamma_{j+1} F'')  =  I^{j-2} / I^{j-1} .
// Hence  A_c := gamma_2/(gamma_{c+1} F'')  =  Z[S,T]/(S,T)^{c-1} . w ,
// with Z-basis the monomials S^a T^b , a+b <= c-2  (rank c(c-1)/2).
//
// Dictionary (verified below against the independent Magnus computation in
// docs/scout/class4.mjs):
//    w = 1 ,  p = [w,x] = S ,  q = [w,y] = T ,
//    r1 = [p,x] = S^2 , r2 = [p,y] = [q,x] = ST , r3 = [q,y] = T^2 .
//    theta (x<->y) :  f.w  |->  -f(T,S).w                (theta(w) = w^{-1} exact)
//    tau  (x->y->z->x, z=(xy)^{-1}) :  f(s,t).w |-> f(t,(st)^{-1}) . s^{-1} w
//    sigma_m = Ad(Y^m) o tau :  f |-> t^m . tau(f)
//    E_m = X^m Z^m Y^m  =  c_m - s^{-m} A_m(s) A_m(st) ,  A_m(u)=1+u+...+u^{m-1},
//         c_m = t A_{m-1}(st) + t c_{m-1} , c_1 = 0     (from x^m y^m = (xy)^m c_m)
//
// Output: for each class c and each m, Z_2-solvability (= solvability mod 2^j
// for EVERY j) of      (1+theta) f = 0   and   N f = -E_m  ,  N = 1+sigma+sigma^2,
// decided by integer Smith normal form (elementary divisors + compatibility).
// Exact BigInt throughout; no external input.
//
//   usage:  node metab.mjs [maxClass] [maxM]        (defaults 7 and 31)
// ===========================================================================
const CMAX = Number(process.argv[2] || 7), MMAX = Number(process.argv[3] || 31);

// ---------- truncated polynomial arithmetic in Z[S,T]/(S,T)^{DG+1} ----------
let DG = 0;                                   // current truncation: total degree <= DG
const key = (a,b)=>a+","+b;
const P0 = ()=>new Map();
const Pc = (c)=>{const m=new Map(); if(c!==0n)m.set("0,0",c); return m;};
const padd=(A,B)=>{const R=new Map(A);for(const[k,v]of B){const u=(R.get(k)||0n)+v;if(u===0n)R.delete(k);else R.set(k,u);}return R;};
const psub=(A,B)=>{const R=new Map(A);for(const[k,v]of B){const u=(R.get(k)||0n)-v;if(u===0n)R.delete(k);else R.set(k,u);}return R;};
const pscal=(A,c)=>{const R=new Map();if(c===0n)return R;for(const[k,v]of A)R.set(k,v*c);return R;};
function pmul(A,B){const R=new Map();
  for(const[k1,v1]of A){const[a1,b1]=k1.split(",").map(Number);
    for(const[k2,v2]of B){const[a2,b2]=k2.split(",").map(Number);
      if(a1+a2+b1+b2>DG)continue; const k=key(a1+a2,b1+b2);
      const u=(R.get(k)||0n)+v1*v2; if(u===0n)R.delete(k); else R.set(k,u);}}
  return R;}
function ppow(A,n){let R=Pc(1n),b=new Map(A);while(n>0){if(n&1)R=pmul(R,b);b=pmul(b,b);n>>=1;}return R;}
// (1+X)^{-1} = sum (-X)^k
function pinvUnit(A){ // A must have constant term 1
  const u=psub(A,Pc(1n)); let R=Pc(1n),t=Pc(1n);
  for(let i=1;i<=DG;i++){t=pmul(t,u); R = i%2 ? psub(R,t) : padd(R,t);} return R;}
const S=()=>{const m=new Map();m.set("1,0",1n);return m;};
const T=()=>{const m=new Map();m.set("0,1",1n);return m;};
const s_=()=>padd(Pc(1n),S()), t_=()=>padd(Pc(1n),T());
// substitution f(S,T) -> f(U,V) for polynomials U,V with zero constant term
function psubst(f,U,V){ let R=P0();
  const Up=[Pc(1n)],Vp=[Pc(1n)];
  for(let i=1;i<=DG;i++){Up.push(pmul(Up[i-1],U));Vp.push(pmul(Vp[i-1],V));}
  for(const[k,v]of f){const[a,b]=k.split(",").map(Number); if(a+b>DG)continue;
    R=padd(R,pscal(pmul(Up[a],Vp[b]),v));}
  return R;}

// ---------- basis / matrices ----------
let BASIS=[], IDX=new Map();
function setClass(c){ DG=c-2; BASIS=[]; IDX=new Map();
  for(let d=0;d<=DG;d++)for(let a=d;a>=0;a--){const b=d-a;IDX.set(key(a,b),BASIS.length);BASIS.push([a,b]);} }
const toVec=(f)=>{const v=new Array(BASIS.length).fill(0n);for(const[k,c]of f){const i=IDX.get(k);if(i!==undefined)v[i]=c;}return v;};
const fromVec=(v)=>{const f=new Map();v.forEach((c,i)=>{if(c!==0n)f.set(key(...BASIS[i]),c);});return f;};

// theta, tau, sigma_m as maps on polynomials
const thetaP=(f)=>pscal(psubst(f,T(),S()),-1n);
function tauP(f){ const invs=pinvUnit(s_()), invt=pinvUnit(t_());
  const rho=psub(pmul(invs,invt),Pc(1n));       // (st)^{-1} - 1
  return pmul(psubst(f,T(),rho),invs); }
const sigmaP=(f,m)=>pmul(ppow(t_(),m),tauP(f));
// E_m
function Em(m){ if(m===0)return P0();
  const s=s_(),t=t_(),st=pmul(s,t);
  const A=(u,n)=>{let R=P0(),p=Pc(1n);for(let i=0;i<n;i++){R=padd(R,p);p=pmul(p,u);}return R;};
  let c=P0();                                    // c_1 = 0
  for(let k=2;k<=m;k++) c=padd(pmul(t,A(st,k-1)),pmul(t,c));
  const inv_sm=ppow(pinvUnit(s),m);
  return psub(c, pmul(inv_sm,pmul(A(s,m),A(st,m)))); }

const matOf=(op)=>BASIS.map((_,i)=>{const e=new Array(BASIS.length).fill(0n);e[i]=1n;return toVec(op(fromVec(e)));});
const mm=(A,B)=>A.map(r=>{const o=new Array(A.length).fill(0n);r.forEach((c,i)=>B[i].forEach((v,j)=>o[j]+=c*v));return o;});
const ma=(...M)=>M[0].map((_,i)=>M[0][i].map((_,j)=>M.reduce((s,X)=>s+X[i][j],0n)));
const idm=(n)=>[...Array(n)].map((_,i)=>[...Array(n)].map((_,j)=>i===j?1n:0n));
const apv=(M,v)=>{const o=new Array(v.length).fill(0n);v.forEach((c,i)=>M[i].forEach((x,j)=>o[j]+=c*x));return o;};

// ---------- integer Smith normal form (returns diagonal + row transform U) ----
function snf(Min){ const A=Min.map(r=>r.slice()); const n=A.length,mc=A[0].length;
  const U=idm(n); let r=0; const dia=[];
  for(let t=0;t<Math.min(n,mc)&&r<n;t++){
    let pi=-1,pj=-1,best=0n;
    for(let i=r;i<n;i++)for(let j=t;j<mc;j++){const v=A[i][j]<0n?-A[i][j]:A[i][j];if(v!==0n&&(best===0n||v<best)){best=v;pi=i;pj=j;}}
    if(pi<0)break;
    [A[r],A[pi]]=[A[pi],A[r]]; [U[r],U[pi]]=[U[pi],U[r]];
    for(let i=0;i<n;i++){const tm=A[i][t];A[i][t]=A[i][pj];A[i][pj]=tm;}
    let again=true;
    while(again){again=false;
      for(let i=r+1;i<n;i++) if(A[i][t]!==0n){const q=A[i][t]/A[r][t];
        for(let j=0;j<mc;j++)A[i][j]-=q*A[r][j]; for(let j=0;j<n;j++)U[i][j]-=q*U[r][j];
        if(A[i][t]!==0n){[A[r],A[i]]=[A[i],A[r]];[U[r],U[i]]=[U[i],U[r]];again=true;}}
      for(let j=t+1;j<mc;j++) if(A[r][j]!==0n){const q=A[r][j]/A[r][t];
        for(let i=0;i<n;i++)A[i][j]-=q*A[i][t];
        if(A[r][j]!==0n){for(let i=0;i<n;i++){const tm=A[i][t];A[i][t]=A[i][j];A[i][j]=tm;}again=true;}}}
    dia.push(A[r][t]); r++; }
  return {U,dia,rank:r};}
const v2=(n)=>{if(n===0n)return Infinity;let v=0;n=n<0n?-n:n;while(n%2n===0n){n/=2n;v++;}return v;};

// =========================== self-tests ====================================
console.log("=== self-tests (model vs. independently computed class-4 Magnus data) ===");
let fails=0; const TT=(n,c,x="")=>{console.log((c?"PASS  ":"FAIL  ")+n+(x?"   "+x:""));if(!c)fails++;};
setClass(4);
const eq=(f,g)=>toVec(f).join(",")===toVec(g).join(",");
TT("theta^2 = id", eq(thetaP(thetaP(S())),S()) && eq(thetaP(thetaP(Pc(1n))),Pc(1n)));
TT("tau^3 = id", BASIS.every((_,i)=>{const e=new Array(BASIS.length).fill(0n);e[i]=1n;
    const f=fromVec(e); return eq(tauP(tauP(tauP(f))),f);}));
TT("theta(w)=w^-1 exact", toVec(thetaP(Pc(1n))).join(",")===toVec(pscal(Pc(1n),-1n)).join(","));
TT("tau(w) = w - p + r1", toVec(tauP(Pc(1n))).join(",")===[1n,-1n,0n,1n,0n,0n].join(","));
TT("tau(p) = q - r2",     toVec(tauP(S())).join(",")     ===[0n,0n,1n,0n,-1n,0n].join(","));
TT("tau(q) = -p-q+2r1+2r2+r3", toVec(tauP(T())).join(",")===[0n,-1n,-1n,2n,2n,1n].join(","));
TT("E_1 = [-1,1,0,-1,0,0]", toVec(Em(1)).join(",")===[-1n,1n,0n,-1n,0n,0n].join(","));
TT("E_2 = [-3,4,-1,-5,1,0]", toVec(Em(2)).join(",")===[-3n,4n,-1n,-5n,1n,0n].join(","));
TT("E_3 = [-6,10,-4,-15,5,-1]", toVec(Em(3)).join(",")===[-6n,10n,-4n,-15n,5n,-1n].join(","));
// prop E1:  theta tau theta = iota_x o tau^{-1}   (iota_x = multiplication by s)
{ const ok=BASIS.every((_,i)=>{const e=new Array(BASIS.length).fill(0n);e[i]=1n;const f=fromVec(e);
    const lhs=thetaP(tauP(thetaP(f)));  const rhs=pmul(s_(),tauP(tauP(f)));   // tau^{-1}=tau^2
    return eq(lhs,rhs);});
  TT("Prop E1: theta.tau.theta = iota_x o tau^{-1}", ok); }
// sigma_m(E_m) = E_m
{ let ok=true; for(let m=0;m<=6;m++) if(!eq(sigmaP(Em(m),m),Em(m))) ok=false;
  TT("sigma_m(E_m) = E_m  (m=0..6)", ok); }
// the class-4 closed identity   3 E_m = -T_m kappa_m + B_m rho
{ let ok=true;
  for(let m=0;m<=12;m++){ const sm=matOf(f=>sigmaP(f,m)); const N=ma(idm(6),sm,mm(sm,sm));
    const kap=apv(N,[1n,0n,0n,0n,0n,0n]); const rho=[0n,0n,0n,1n,1n,1n];
    const Tm=BigInt(m*(m+1)/2), Bm=Tm*(Tm+1n)/2n; const e=toVec(Em(m));
    for(let i=0;i<6;i++) if(3n*e[i] !== -Tm*kap[i]+Bm*rho[i]) ok=false; }
  TT("Lemma E9.2' : 3E_m = -T_m kappa_m + B_m rho  (m=0..12)", ok); }
// N(p+q) = 3 rho
{ let ok=true; for(let m=0;m<=8;m++){const sm=matOf(f=>sigmaP(f,m));const N=ma(idm(6),sm,mm(sm,sm));
    const v=apv(N,[0n,1n,1n,0n,0n,0n]); if(v.join(",")!==[0n,0n,0n,3n,3n,3n].join(","))ok=false;}
  TT("Lemma A : N(p+q) = 3(r1+r2+r3), independent of m", ok); }
console.log(fails?`\n*** ${fails} SELF-TEST FAILURES -- results below are void ***\n`:"\n--- all self-tests passed ---\n");
if (fails) { console.error(`FATAL: ${fails} self-test failures -- exiting nonzero (F8-4)`); process.exit(1); }

// ---------- F8-3 dump: serialize M,b per docs/week4-E19二系統化指示書_v1.md sec.1.4, with hashes ----
import { createHash } from 'node:crypto';
import { mkdirSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
const __dirname_ = dirname(fileURLToPath(import.meta.url));
const DUMP_DIR = join(__dirname_, '..', '..', 'certificates', 'e19');
function sha256hex(s) { return createHash('sha256').update(s, 'utf8').digest('hex'); }
function dumpSystem(c, m, rows, rhs) {
  mkdirSync(DUMP_DIR, { recursive: true });
  const rowStrs = rows.map((r) => r.map((x) => x.toString()).join(','));
  const Mstr = rowStrs.join(';');
  const bStr = rhs.map((x) => x.toString()).join(',');
  const MHash = sha256hex(Mstr);
  const bHash = sha256hex(bStr);
  const content = `M=${Mstr}\nb=${bStr}\n`;
  writeFileSync(join(DUMP_DIR, `system_c${c}_m${m}.txt`), content);
  return { MHash, bHash };
}
const DUMP_CMIN = Number(process.env.E19_DUMP_CMIN || 0), DUMP_CMAX = Number(process.env.E19_DUMP_CMAX || -1);
if (DUMP_CMAX >= DUMP_CMIN) {
  console.log(`\n=== dumping M,b for c=${DUMP_CMIN}..${DUMP_CMAX}, m=0..${MMAX} (F8-3) ===`);
  const hashLog = [];
  for (let c = DUMP_CMIN; c <= DUMP_CMAX; c++) {
    setClass(c); const n = BASIS.length;
    const th = matOf(thetaP), OT = ma(idm(n), th);
    for (let m = 0; m <= MMAX; m++) {
      const sm = matOf((f) => sigmaP(f, m)); const N = ma(idm(n), sm, mm(sm, sm));
      const b = toVec(Em(m));
      const rows = [], rhs = [];
      for (let i = 0; i < n; i++) { const r = new Array(n).fill(0n); for (let k = 0; k < n; k++) r[k] = OT[k][i]; rows.push(r); rhs.push(0n); }
      for (let i = 0; i < n; i++) { const r = new Array(n).fill(0n); for (let k = 0; k < n; k++) r[k] = N[k][i]; rows.push(r); rhs.push(-b[i]); }
      const { MHash, bHash } = dumpSystem(c, m, rows, rhs);
      hashLog.push({ c, m, M_content_hash: MHash, b_content_hash: bHash });
    }
  }
  writeFileSync(join(DUMP_DIR, 'node_hashes.json'), JSON.stringify(hashLog));
  console.log(`wrote ${hashLog.length} dump files + node_hashes.json to ${DUMP_DIR}`);
}

// ======================= main sweep ========================================
console.log("class | rank A | m-range | Z_2-solvable for all m ? | max v2(elementary divisor) | note");
for(let c=3;c<=CMAX;c++){
  setClass(c); const n=BASIS.length;
  const th=matOf(thetaP), OT=ma(idm(n),th);
  let allSolv=true, maxv=0, badList=[];
  for(let m=0;m<=MMAX;m++){
    const sm=matOf(f=>sigmaP(f,m)); const N=ma(idm(n),sm,mm(sm,sm));
    const b=toVec(Em(m));
    const rows=[],rhs=[];
    for(let i=0;i<n;i++){const r=new Array(n).fill(0n);for(let k=0;k<n;k++)r[k]=OT[k][i];rows.push(r);rhs.push(0n);}
    for(let i=0;i<n;i++){const r=new Array(n).fill(0n);for(let k=0;k<n;k++)r[k]=N[k][i];rows.push(r);rhs.push(-b[i]);}
    const {U,dia}=snf(rows);
    const cc=U.map(u=>u.reduce((s,uv,j)=>s+uv*rhs[j],0n));
    let solv=true;
    for(let i=0;i<dia.length;i++){maxv=Math.max(maxv,v2(dia[i])); if(v2(cc[i])<v2(dia[i]))solv=false;}
    for(let i=dia.length;i<cc.length;i++) if(cc[i]!==0n) solv=false;
    if(!solv){allSolv=false;badList.push(m);}
  }
  console.log(`  ${c}  |   ${n}   | 0..${MMAX} | ${allSolv?"YES":"*** NO at m = "+badList.join(",")+" ***"} | ${maxv} | ${maxv===0?"all elementary divisors ODD => no 2-adic obstruction for ANY right-hand side":"2-power divisors present"}`);
}

// ============ graded obstruction: is theta = -1 on gr_j(A)^tau ? ============
console.log("\n=== graded 2-primary obstruction  O_j = (1+theta)|_{gr_j^tau}  ===");
console.log("(weight j ; rank gr_j ; rank gr_j^tau ; is theta = -1 there ?)");
setClass(CMAX);
for(let j=2;j<=CMAX;j++){
  const d=j-2; const idxs=BASIS.map((b,i)=>[b,i]).filter(([b])=>b[0]+b[1]===d).map(([,i])=>i);
  // tau and theta on gr_j : take matrices and restrict to the degree-d block
  const th=matOf(thetaP), ta=matOf(tauP);
  const sub=(M)=>idxs.map(i=>idxs.map(j2=>M[i][j2]));
  const TH=sub(th), TA=sub(ta), k=idxs.length;
  // fixed space of TA over Q (rational nullspace of TA - I) ; then test TH = -1 on it
  const A0=[]; for(let i=0;i<k;i++){const r=[];for(let j2=0;j2<k;j2++)r.push((TA[j2][i]||0n)-(i===j2?1n:0n));A0.push(r);}
  // rational nullspace by fraction-free elimination
  const M2=A0.map(r=>r.slice()); const piv=[]; let rr=0;
  for(let cc2=0;cc2<k&&rr<k;cc2++){let pr=-1;for(let i=rr;i<k;i++)if(M2[i][cc2]!==0n){pr=i;break;}
    if(pr<0)continue;[M2[rr],M2[pr]]=[M2[pr],M2[rr]];
    for(let i=0;i<k;i++)if(i!==rr&&M2[i][cc2]!==0n){const a=M2[rr][cc2],b2=M2[i][cc2];
      for(let j2=0;j2<k;j2++)M2[i][j2]=M2[i][j2]*a-M2[rr][j2]*b2;}
    piv.push(cc2);rr++;}
  const free=[...Array(k).keys()].filter(i=>!piv.includes(i));
  const basisFix=free.map(fc=>{const v=new Array(k).fill(0n);v[fc]=1n;
    piv.forEach((pc,ri)=>{v[pc]=-M2[ri][fc];});
    // scale by pivot values
    const sc=piv.map((pc,ri)=>M2[ri][pc]); let L=1n; sc.forEach(x=>{L=L*x/((a,b)=>{a=a<0n?-a:a;b=b<0n?-b:b;while(b){[a,b]=[b,a%b];}return a;})(L,x);});
    const v2b=v.map(z=>z); piv.forEach((pc,ri)=>{v2b[pc]=-M2[ri][fc]*(L/sc[ri]);}); v2b[fc]=L;
    return v2b;});
  let minusOne=true;
  for(const v of basisFix){ const im=apv(TH,v); if(!im.every((z,i)=>z===-v[i])) minusOne=false; }
  console.log(` j=${j} : rank gr_j = ${k} ; rank gr_j^tau = ${basisFix.length} ; theta = -1 on it ? ${basisFix.length===0?"(vacuous)":(minusOne?"YES  => O_j = 0":"NO   => O_j != 0  (obstruction possible)")}`);
}
